mapper.select:
SELECT * FROM order_info
WHERE deleted = 0

    AND status = #{status}


    AND order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND receiver_phone LIKE CONCAT('%', #{phone}, '%')


    AND receiver_name LIKE CONCAT('%', #{receiverName}, '%')


    AND id IN (
        SELECT DISTINCT oi.order_id FROM order_item oi
        WHERE oi.deleted = 0 AND oi.product_name LIKE CONCAT('%', #{productName}, '%')
    )


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}


    AND pay_time >= #{payStartTime}


    AND pay_time <= #{payEndTime}

ORDER BY create_time DESC

SELECT COUNT(*) FROM order_info
WHERE deleted = 0

    AND user_id = #{userId}


    AND status = #{status}
